```tsx
import { useEffect, useId, useState } from "react";
import "./CodeCard.css";

export interface CodeCardProps {
  title: string;
  code: string;
  onCopy: () => void;
}

const STATUS_MS = 2000;

export function CodeCard({ title, code, onCopy }: CodeCardProps) {
  const titleId = useId();
  const [copiedAt, setCopiedAt] = useState<number | null>(null);

  useEffect(() => {
    if (copiedAt === null) return;
    const timer = window.setTimeout(() => setCopiedAt(null), STATUS_MS);
    return () => window.clearTimeout(timer);
  }, [copiedAt]);

  const handleCopy = () => {
    onCopy();
    setCopiedAt(Date.now());
  };

  return (
    <section className="code-card" aria-labelledby={titleId}>
      <header className="code-card__header">
        <h2 id={titleId} className="code-card__title">
          {title}
        </h2>
        <button
          type="button"
          className="code-card__copy"
          onClick={handleCopy}
        >
          Copy
        </button>
      </header>

      <pre
        className="code-card__block"
        tabIndex={0}
        aria-label={`${title} SQL`}
      >
        <code>{code}</code>
      </pre>

      <span className="code-card__status" role="status">
        {copiedAt !== null ? "Copied" : ""}
      </span>
    </section>
  );
}
```

