  border-radius: 12px;
  background: var(--slide);
  color: var(--ink);
  font: inherit;
}

.code-card__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.code-card__title {
  margin: 0;
  font: inherit;
  font-size: clamp(0.95rem, 0.9rem + 0.3vw, 1.125rem);
  font-weight: 600;
  color: var(--ink);
}

.code-card__copy {
  font: inherit;
  font-size: clamp(0.8rem, 0.78rem + 0.2vw, 0.9rem);
  padding: 0.35rem 0.9rem;
  border: 1px solid var(--ink);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}

.code-card__block {
  margin: 0;
  padding: clamp(0.75rem, 1vw, 1rem);
  overflow-x: auto;
  border-radius: 8px;
  background: var(--code-bg);
  color: var(--ink);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
  font-size: clamp(0.8rem, 0.76rem + 0.2vw, 0.9rem);
  line-height: 1.5;
  white-space: pre;
  font-variant-numeric: tabular-nums;
}

.code-card__status {
  min-height: 1.25em;
  font-size: clamp(0.75rem, 0.72rem + 0.2vw, 0.85rem);
  color: var(--muted);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.code-card__copy:hover {
  background: var(--myelin-wash);
}

:root:not([data-motion="reduce"]) .code-card__copy {
  transition: background-color 150ms ease;
}

@media (prefers-reduced-motion: reduce) {
  .code-card__copy {
    transition: none;
  }
}

:root[data-motion="reduce"] .code-card__copy {
  transition: none;
}
